id: vuln-spark-cf59b1f5
languages:
  - java
message: "Potential security vulnerability: The exception message reveals sensitive information."
severity: ERROR
metadata:
  cve: CVE-2024-23945
  cwe: CWE-209
pattern: |
  import java.security.MessageDigest;
  import java.security.NoSuchAlgorithmException;
  import org.apache.commons.codec.binary.Base64;
  import org.slf4j.Logger;
  import org.slf4j.LoggerFactory;

  public class CookieSigner {
    public String verifyAndExtract(String signedStr) {
      int index = signedStr.lastIndexOf(SIGNATURE);
      if (index == -1) {
        throw new IllegalArgumentException("Invalid input sign: " + signedStr);
      }
      String originalSignature = signedStr.substring(index + SIGNATURE.length());
      String rawValue = signedStr.substring(0, index);
      String currentSignature = getSignature(rawValue);

      if (LOG.isDebugEnabled()) {
        LOG.debug("Signature generated for " + rawValue + " inside verify is " + currentSignature);
      }
      if (!MessageDigest.isEqual(originalSignature.getBytes(), currentSignature.getBytes())) {
        throw new IllegalArgumentException("Invalid sign, original = " + originalSignature +
          " current = " + currentSignature);
      }
      return rawValue;
    }
  }
taint-mode:
  language: java
  taint-annotation: org.semgrep.semgrep_core.Taint
  sink-methods:
    - "java.lang.IllegalArgumentException.<init>(..)"
```
This Semgrep rule will detect the vulnerable behavior in the `verifyAndExtract` method of the `CookieSigner` class. The rule is written in YAML format and will match the vulnerable code snippet. The `taint-mode` field is used to identify the sink method that the taint flows to. In this case, the taint flows to the `IllegalArgumentException` constructor, which is a common place for sensitive information to be logged or displayed.

